-- Diagnóstico MANUAL de solo lectura. No ejecutado por el agente.
-- Ejecutar como postgres en Supabase, fuera de la transacción abortada anterior.
-- Devolver TODAS las filas y los textos completos (exportar si el editor los trunca).
-- No invoca RPC de negocio, no lee pedidos ni cambia funciones/permisos/datos.
-- Los cuerpos esperados son los textos locales de Fase 2 con LF, codificados
-- en hexadecimal para que el transporte del diagnóstico no altere sus saltos.
-- Igualdad CRLF/LF es evidencia de formato, NO autorización de instalación.
-- Una desigualdad normalizada exige comparar el cuerpo íntegro; puede ser
-- formato adicional, comentarios, literales o cambios funcionales.
WITH esperados(firma, nombre, md5_exigido_fase3, cuerpo_local_lf) AS (
 VALUES
('public.operar_ruta_multiple(jsonb)', 'operar_ruta_multiple', '3e7bedaabab7ed3dd7058cafa3fb1f21', convert_from(decode('', 'hex'), 'UTF8')),
('public.leer_rutas_multiples(date)', 'leer_rutas_multiples', '5438a8139ed3f3845e618380ce2b6794', convert_from(decode('', 'hex'), 'UTF8')),
('public.leer_mi_reparto()', 'leer_mi_reparto', 'bbeb502fd8085565c72e0f71f6f5b588', convert_from(decode('', 'hex'), 'UTF8'))
), comparacion AS (
 SELECT e.*, p.oid, p.proowner, p.prosrc,
        replace(p.prosrc, chr(13)||chr(10), chr(10)) AS cuerpo_instalado_lf
 FROM esperados e LEFT JOIN pg_catalog.pg_proc p
 ON p.oid=pg_catalog.to_regprocedure(e.firma)
), salida AS (
 SELECT '01_contexto'::text AS seccion, 'sesion'::text AS objeto,
 jsonb_build_object('current_user',current_user,'session_user',session_user,
 'version',version(),'encoding',current_setting('server_encoding'),
 'search_path',current_setting('search_path'),
 'transaction_isolation',current_setting('transaction_isolation'),
 'session_replication_role',current_setting('session_replication_role'),
 'rolsuper',r.rolsuper,'rolbypassrls',r.rolbypassrls,
 'rutas_multi',to_regclass('operativo_privado.rutas_multi')::text) AS detalle
 FROM pg_catalog.pg_roles r WHERE r.rolname=current_user
 UNION ALL
 SELECT '02_comparacion',firma,jsonb_build_object(
 'existe_firma_exacta',oid IS NOT NULL,
 'propietario',pg_get_userbyid(proowner),
 'md5_exigido_fase3',md5_exigido_fase3,
 'md5_instalado',md5(prosrc),'md5_instalado_lf',md5(cuerpo_instalado_lf),
 'md5_local_lf',md5(cuerpo_local_lf),
 'precondicion_actual_fase3',coalesce(pg_get_userbyid(proowner)='postgres' AND md5(prosrc)=md5_exigido_fase3,false),
 'cuerpo_identico_local',prosrc=cuerpo_local_lf,
 'cuerpo_identico_solo_normalizando_crlf',cuerpo_instalado_lf=cuerpo_local_lf,
 'caracteres',length(prosrc),'bytes',octet_length(prosrc),
 'cantidad_cr',length(prosrc)-length(replace(prosrc,chr(13),'')),
 'cantidad_lf',length(prosrc)-length(replace(prosrc,chr(10),'')),
 'cantidad_crlf',(length(prosrc)-length(replace(prosrc,chr(13)||chr(10),'')))/2,
 'cr_aislado',strpos(cuerpo_instalado_lf,chr(13))>0,
 'cuerpo_instalado',prosrc,
 'cuerpo_instalado_utf8_hex',encode(convert_to(prosrc,'UTF8'),'hex'))
 FROM comparacion
 UNION ALL
 -- Todas las sobrecargas, incluso si la firma exacta falta.
 SELECT '03_definiciones_y_sobrecargas',p.oid::regprocedure::text,
 jsonb_build_object('oid',p.oid,'esquema',n.nspname,'nombre',p.proname,
 'propietario',pg_get_userbyid(p.proowner),'lenguaje',l.lanname,
 'tipo_objeto',p.prokind,'argumentos_identidad',pg_get_function_identity_arguments(p.oid),
 'argumentos',pg_get_function_arguments(p.oid),'nombres_argumentos',p.proargnames,
 'modos_argumentos',p.proargmodes,'tipos_argumentos',p.proargtypes::text,
 'retorno',pg_get_function_result(p.oid),'retorna_conjunto',p.proretset,
 'security_definer',p.prosecdef,'volatilidad',p.provolatile,'strict',p.proisstrict,
 'parallel',p.proparallel,'leakproof',p.proleakproof,'configuracion',p.proconfig,
 'acl',p.proacl::text,
 'execute_public',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
 where a.grantee=0 and a.privilege_type='EXECUTE'),
 'permisos_roles_api',(select jsonb_object_agg(r.rolname,has_function_privilege(r.oid,p.oid,'EXECUTE'))
 from pg_roles r where r.rolname in ('anon','authenticated','service_role')),
 'definicion_completa',case when p.prokind in ('f','p') then pg_get_functiondef(p.oid) end)
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_language l ON l.oid=p.prolang
 WHERE n.nspname='public' AND p.proname IN (select nombre from esperados)
 UNION ALL
 SELECT '04_dependencias',d.firma,jsonb_build_object('existe',p.oid IS NOT NULL,
 'propietario',pg_get_userbyid(p.proowner),
 'definicion_completa',case when p.prokind in ('f','p') then pg_get_functiondef(p.oid) end)
 FROM (VALUES
 ('public.confirmar_entrega_todo_correcto(uuid,bigint,uuid,jsonb,jsonb)'),
 ('public.registrar_entrega_fallida(uuid,bigint,uuid,text,text)'),
 ('operativo_privado.iniciar_operacion(uuid,bigint,uuid,text,jsonb)'),
 ('operativo_privado.completar_operacion(uuid,bigint,uuid,text,jsonb,uuid,text,jsonb,jsonb,jsonb)'),
 ('operativo_privado.permiso_reparto(uuid,date)'),
 ('operativo_privado.leer_mi_reparto()')) d(firma)
 LEFT JOIN pg_proc p ON p.oid=to_regprocedure(d.firma)
 UNION ALL
 SELECT '05_aislamiento',r.rolname,jsonb_build_object(
 'usage_privado',has_schema_privilege(r.oid,n.oid,'USAGE'),
 'create_privado',has_schema_privilege(r.oid,n.oid,'CREATE'),
 'create_public',has_schema_privilege(r.oid,'public','CREATE'))
 FROM pg_roles r LEFT JOIN pg_namespace n ON n.nspname='operativo_privado'
 WHERE r.rolname IN ('anon','authenticated','service_role')
)
SELECT seccion,objeto,detalle FROM salida ORDER BY seccion,objeto;
